package org.sleepwell.app;
import android.content.*;import android.database.sqlite.SQLiteDatabase;import java.time.*;import java.util.*;
/** Explicit apply/retry/cancel only. Reading a recovery journal performs no scheduling or backfill. */
final class NapProfilesRuntime {
 final Context context;final NapProfilesStore profiles;NapProfilesRuntime(Context context){this.context=context.getApplicationContext();profiles=new NapProfilesStore(this.context);}
 NapProfiles.Review review(String id,int revision,LocalDate day){NapProfiles.Profile profile=profiles.profile(id);if(profile.revision!=revision)throw new IllegalArgumentException("Profile changed. Reopen it before review.");NapPlan.Clock clock=Naps.clock(context);return new NapProfiles.Review(profile,day,ZoneId.systemDefault(),clock.wall(),clock.elapsed(),clock.boot(),clock.device());}
 NapProfiles.Batch apply(NapProfiles.Review review){synchronized(Scheduler.class){NapProfiles.Profile current=profiles.profile(review.profile.id);if(current.revision!=review.profile.revision)throw new IllegalArgumentException("Profile changed. Review its saved version.");NapPlan.Clock clock=Naps.clock(context);review.check(clock,ZoneId.systemDefault());access();for(NapProfiles.Batch old:profiles.read().batches)if(old.review.profile.id.equals(current.id)&&old.review.profile.revision==current.revision&&old.review.day.equals(review.day)&&!old.stage.equals("CANCELLED"))throw new IllegalArgumentException("This profile/date already has an application. Review that application before creating another.");List<NapProfiles.Row> rows=new ArrayList<>();try(Store store=Records.open(context)){int maximum=store.alarms().stream().mapToInt(a->a.id).max().orElse(0);if(maximum>Integer.MAX_VALUE-current.entries.size())throw new IllegalStateException("No alarm slots are available.");long pinnedWall=clock.wall(),pinnedElapsed=clock.elapsed(),pinnedBoot=clock.boot();String pinnedDevice=clock.device();NapPlan.Clock frozen=new NapPlan.Clock(){public long wall(){return pinnedWall;}public long elapsed(){return pinnedElapsed;}public long boot(){return pinnedBoot;}public String device(){return pinnedDevice;}};for(int n=0;n<current.entries.size();n++){NapProfiles.Entry entry=current.entries.get(n);Alarm alarm=new Alarm(maximum+n+1);alarm.smartWindow=0;alarm.enabled=false;alarm.label=current.name+" · "+(n+1);alarm.nap=NapPlan.create(frozen,entry.duration,review.starts.get(n)-frozen.wall(),true);java.time.ZonedDateTime end=Instant.ofEpochMilli(alarm.nap.deadlineWall()).atZone(review.zone);alarm.hour=end.getHour();alarm.minute=end.getMinute();rows.add(new NapProfiles.Row(alarm.id,alarm.json().toString(),false,false));}}
  NapProfiles.Batch batch=new NapProfiles.Batch(UUID.randomUUID().toString(),review,rows,"PREPARED","",false,false);profiles.put(batch);return finish(batch);
 }}
 private void access(){if(Prefs.flag(context,"ringing"))throw new IllegalStateException("Finish the active alarm before applying a profile.");Notifications.channels(context);String denied=Naps.ports.create(context).access();if(!denied.isEmpty())throw new SecurityException(denied);}
 NapProfiles.Batch retry(String id){synchronized(Scheduler.class){return finish(profiles.batch(id));}}
 private NapProfiles.Batch finish(NapProfiles.Batch initial){NapProfiles.Batch batch=initial;try{if(batch.cancellation||batch.stage.equals("CANCELLED"))throw new IllegalArgumentException("This batch was cancelled. Apply a newly reviewed profile instead.");access();List<NapProfiles.Row> rows=new ArrayList<>(batch.rows);boolean allActive=true;try(Store store=Records.open(context)){for(NapProfiles.Row row:rows){Alarm actual=store.alarm(row.id);if(actual==null||!owned(batch,row,actual)||!actual.enabled)allActive=false;}}
  if(batch.activation&&allActive){rows=currentRows(batch);batch=batch.change(rows,"SCHEDULED","Existing timers are already active; no backfill was scheduled.",true,false);profiles.put(batch);return batch;}if(batch.stage.equals("SCHEDULED"))throw new IllegalArgumentException("This application was already activated. Open individual naps; completed timers are never recreated.");batch.review.check(Naps.clock(context),ZoneId.systemDefault());
  try(Store store=Records.open(context)){SQLiteDatabase db=store.getWritableDatabase();db.beginTransaction();try{for(NapProfiles.Row row:rows){Alarm actual=store.alarm(row.id);if(actual==null){if(!batch.stage.equals("PREPARED"))throw new IllegalArgumentException("An applied timer was removed. It will not be recreated.");store.save(row.alarm());actual=store.alarm(row.id);}if(actual==null||!owned(batch,row,actual)||actual.enabled||actual.nap.phase!=NapPlan.Phase.PENDING)throw new IllegalArgumentException("A timer was changed or started. It was not replaced.");if(!actual.json().toString().equals(row.snapshot))throw new IllegalArgumentException("Timer ownership changed. Review this application.");}db.setTransactionSuccessful();}finally{db.endTransaction();}}
  batch=batch.change(rows,"CREATED","",false,false);profiles.put(batch);
  for(int n=0;n<rows.size();n++){batch.review.check(Naps.clock(context),ZoneId.systemDefault());access();NapProfiles.Row row=rows.get(n);Alarm actual;try(Store store=Records.open(context)){actual=store.alarm(row.id);}if(actual==null||!actual.json().toString().equals(row.snapshot)||actual.enabled||actual.nap.phase!=NapPlan.Phase.PENDING)throw new IllegalArgumentException("A timer changed. Remaining scheduling was stopped.");Naps.ports.create(context).schedule(actual.id,actual.nap,actual.nap.remaining(Naps.clock(context)));rows.set(n,row.scheduled());batch=batch.change(rows,"SCHEDULING","",false,false);profiles.put(batch);}
  batch.review.check(Naps.clock(context),ZoneId.systemDefault());batch=batch.change(rows,"ACTIVATING","",true,false);profiles.put(batch);List<NapProfiles.Row> active=new ArrayList<>();try(Store store=Records.open(context)){SQLiteDatabase db=store.getWritableDatabase();db.beginTransaction();try{for(NapProfiles.Row row:rows){Alarm actual=store.alarm(row.id);if(actual==null||!actual.json().toString().equals(row.snapshot)||actual.enabled||actual.nap.phase!=NapPlan.Phase.PENDING)throw new IllegalArgumentException("Timer ownership changed before activation.");actual.enabled=true;store.save(actual);Alarm saved=store.alarm(row.id);if(saved==null||!saved.json().toString().equals(actual.json().toString()))throw new IllegalStateException("Profile timer activation could not be verified.");active.add(row.snapshot(saved.json().toString()));}db.setTransactionSuccessful();}finally{db.endTransaction();}}batch=batch.change(active,"SCHEDULED","",true,false);profiles.put(batch);return batch;
 }catch(RuntimeException failure){String message=notice(failure);NapProfiles.Batch attention=batch.change(batch.rows,batch.stage.equals("PREPARED")?"PREPARED":"ATTENTION",message,batch.activation,batch.cancellation);try{profiles.put(attention);return attention;}catch(RuntimeException journal){throw new IllegalStateException(message+" Application status could not be updated; reopen its recovery record.",journal);}}}
 private boolean owned(NapProfiles.Batch batch,NapProfiles.Row row,Alarm actual){if(actual==null||actual.id!=row.id||actual.nap==null||actual.napInvalid||!actual.nap.nonce.equals(row.alarm().nap.nonce))return false;String raw=actual.json().toString();if(raw.equals(row.snapshot))return true;Alarm expected=row.alarm();if(batch.activation){expected.enabled=true;if(raw.equals(expected.json().toString()))return true;}if(batch.cancellation){expected=row.alarm();expected.enabled=false;expected.nap=expected.nap.state(NapPlan.Phase.CANCELLED,"");if(raw.equals(expected.json().toString()))return true;}return false;}
 private List<NapProfiles.Row> currentRows(NapProfiles.Batch batch){List<NapProfiles.Row> rows=new ArrayList<>();try(Store store=Records.open(context)){for(NapProfiles.Row row:batch.rows){Alarm actual=store.alarm(row.id);if(!owned(batch,row,actual))throw new IllegalArgumentException("A timer changed. It was not touched.");rows.add(row.snapshot(actual.json().toString()));}}return rows;}
 NapProfiles.Batch cancel(String id){synchronized(Scheduler.class){NapProfiles.Batch batch=profiles.batch(id);batch=batch.change(batch.rows,"CANCELLING","",batch.activation,true);profiles.put(batch);List<NapProfiles.Row> rows=new ArrayList<>(batch.rows);int conflicts=0;try(Store store=Records.open(context)){SQLiteDatabase db=store.getWritableDatabase();db.beginTransaction();try{for(int n=0;n<rows.size();n++){NapProfiles.Row row=rows.get(n);Alarm actual=store.alarm(row.id);if(actual==null){rows.set(n,row.cancelled());continue;}if(!owned(batch,row,actual)||actual.nap.phase==NapPlan.Phase.CLAIMED||actual.nap.phase==NapPlan.Phase.FINISHED){conflicts++;continue;}actual.enabled=false;actual.nap=actual.nap.state(NapPlan.Phase.CANCELLED,"");store.save(actual);Alarm saved=store.alarm(row.id);if(saved==null||!saved.json().toString().equals(actual.json().toString()))throw new IllegalStateException("Timer cancellation could not be saved.");rows.set(n,row.snapshot(saved.json().toString()));}db.setTransactionSuccessful();}finally{db.endTransaction();}}batch=batch.change(rows,"CANCELLING","",batch.activation,true);profiles.put(batch);String error=conflicts==0?"":conflicts+" changed/completed timer(s) were left untouched. Open them individually.";for(int n=0;n<rows.size();n++){NapProfiles.Row row=rows.get(n);if(row.cancelled)continue;Alarm actual;try(Store store=Records.open(context)){actual=store.alarm(row.id);}if(actual==null){rows.set(n,row.cancelled());continue;}if(!actual.json().toString().equals(row.snapshot)||actual.enabled||actual.nap.phase!=NapPlan.Phase.CANCELLED)continue;try{Naps.ports.create(context).cancel(actual.id,actual.nap);rows.set(n,row.cancelled());}catch(RuntimeException failed){error="Timer rows are disabled, but some system-job cleanup needs retry.";}}boolean done=rows.stream().allMatch(r->r.cancelled);batch=batch.change(rows,done?"CANCELLED":"ATTENTION",error,batch.activation,true);profiles.put(batch);return batch;}}
 void detach(String id){synchronized(Scheduler.class){NapProfiles.Batch batch=profiles.batch(id);if(!batch.stage.equals("SCHEDULED")&&!batch.stage.equals("CANCELLED"))throw new IllegalArgumentException("Resolve or cancel the interrupted application before detaching it.");profiles.detach(id);}}
 static String notice(RuntimeException error){String text=error.getMessage();if(text==null||text.isBlank())return "Profile application needs review. No unrelated timers were replaced.";return text.length()>280?text.substring(0,280):text;}
}
